import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(scriptDir, '..');
const defaultProfilePath = path.join(projectRoot, 'deployment', 'intune', 'profile.json');
const defaultOutputDir = path.join(projectRoot, 'dist', 'intune');

export const EDGE_STORE_UPDATE_URL = 'https://edge.microsoft.com/extensionwebstorebase/v1/crx';
export const CHROME_STORE_UPDATE_URL = 'https://clients2.google.com/service/update2/crx';

const browserConfigs = {
  edge: {
    updateUrl: EDGE_STORE_UPDATE_URL,
    policyRoot: 'HKLM:\\SOFTWARE\\Policies\\Microsoft\\Edge\\3rdparty\\extensions',
    filePrefix: 'edge-extension'
  },
  chrome: {
    updateUrl: CHROME_STORE_UPDATE_URL,
    policyRoot: 'HKLM:\\SOFTWARE\\Policies\\Google\\Chrome\\3rdparty\\extensions',
    filePrefix: 'chrome-extension'
  }
};

export function validateExtensionId(value) {
  const id = String(value || '').trim();
  if (!/^[a-p]{32}$/.test(id)) throw new Error('Extension ID must be 32 lowercase letters from a through p.');
  return id;
}

export function validateManagedPolicy(policy, schema) {
  if (!policy || typeof policy !== 'object' || Array.isArray(policy)) throw new Error('managedPolicy must be an object.');
  const properties = schema?.properties || {};
  const output = {};
  for (const [key, value] of Object.entries(policy)) {
    const definition = properties[key];
    if (!definition) throw new Error(`Unknown managed policy key: ${key}`);
    if (definition.type === 'boolean' && typeof value !== 'boolean') throw new Error(`${key} must be a boolean.`);
    if (definition.type === 'string' && typeof value !== 'string') throw new Error(`${key} must be a string.`);
    if (definition.type === 'array' && (!Array.isArray(value) || value.some(item => typeof item !== definition.items?.type))) {
      throw new Error(`${key} must be an array of ${definition.items?.type || 'valid'} values.`);
    }
    output[key] = value;
  }
  return output;
}

function psQuote(value) {
  return `'${String(value).replaceAll("'", "''")}'`;
}

function policyValueCommands(policy) {
  const commands = [];
  for (const [key, value] of Object.entries(policy)) {
    if (Array.isArray(value)) {
      commands.push(`$arrayPath = $policyPath + ${psQuote(`\\${key}`)}`);
      commands.push('New-Item -Path $arrayPath -Force | Out-Null');
      commands.push('Get-Item -LiteralPath $arrayPath | Select-Object -ExpandProperty Property | ForEach-Object { Remove-ItemProperty -LiteralPath $arrayPath -Name $_ -Force }');
      value.forEach((item, index) => commands.push(`New-ItemProperty -Path $arrayPath -Name ${psQuote(String(index + 1))} -PropertyType String -Value ${psQuote(item)} -Force | Out-Null`));
    } else {
      const type = typeof value === 'boolean' ? 'DWord' : 'String';
      const rendered = typeof value === 'boolean' ? (value ? '1' : '0') : psQuote(value);
      commands.push(`New-ItemProperty -Path $policyPath -Name ${psQuote(key)} -PropertyType ${type} -Value ${rendered} -Force | Out-Null`);
    }
  }
  return commands.join('\n');
}

function remediationScript(extensionId, policy, policyRoot) {
  return `# Generated by Better CaptionKeep. Run as SYSTEM through Intune.\n$ErrorActionPreference = 'Stop'\n$extensionId = ${psQuote(extensionId)}\n$policyPath = "${policyRoot}\\$extensionId\\policy"\nNew-Item -Path $policyPath -Force | Out-Null\n${policyValueCommands(policy)}\nWrite-Output 'Better CaptionKeep managed policy applied.'\n`;
}

function detectionScript(extensionId, policy, policyRoot) {
  const expected = Buffer.from(JSON.stringify(policy), 'utf8').toString('base64');
  return `# Generated by Better CaptionKeep. Exit 0 means compliant; exit 1 requests remediation.\n$extensionId = ${psQuote(extensionId)}\n$policyPath = "${policyRoot}\\$extensionId\\policy"\n$expected = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(${psQuote(expected)})) | ConvertFrom-Json\nif (-not (Test-Path -LiteralPath $policyPath)) { exit 1 }\nforeach ($property in $expected.PSObject.Properties) {\n    $actual = Get-ItemProperty -LiteralPath $policyPath -Name $property.Name -ErrorAction SilentlyContinue\n    if ($property.Value -is [array]) {\n        $arrayPath = Join-Path $policyPath $property.Name\n        if (-not (Test-Path -LiteralPath $arrayPath)) { exit 1 }\n        $stored = Get-ItemProperty -LiteralPath $arrayPath\n        $values = @($stored.PSObject.Properties | Where-Object Name -Match '^\\d+$' | Sort-Object { [int]$_.Name } | ForEach-Object Value)\n        if (Compare-Object @($property.Value) $values) { exit 1 }\n    } elseif ($property.Value -is [bool]) {\n        if ($null -eq $actual -or [int]$actual.($property.Name) -ne [int]$property.Value) { exit 1 }\n    } elseif ($null -eq $actual -or [string]$actual.($property.Name) -ne [string]$property.Value) { exit 1 }\n}\nWrite-Output 'Better CaptionKeep managed policy is compliant.'\nexit 0\n`;
}

export async function buildIntuneBundle(options = {}) {
  const browser = String(options.browser || 'edge').toLowerCase();
  const browserConfig = browserConfigs[browser];
  if (!browserConfig) throw new Error(`Unsupported Intune browser: ${browser}`);
  const profilePath = path.resolve(options.profilePath || defaultProfilePath);
  const outputDir = path.resolve(options.outputDir || defaultOutputDir);
  const profile = JSON.parse(await readFile(profilePath, 'utf8'));
  const schema = JSON.parse(await readFile(path.join(projectRoot, 'teams-captions-saver', 'managed-schema.json'), 'utf8'));
  const extensionId = validateExtensionId(options.extensionId || profile.extensionId);
  const updateUrl = String(profile.updateUrl || browserConfig.updateUrl).trim();
  if (updateUrl !== browserConfig.updateUrl) throw new Error(`The production ${browser} Intune bundle must use its official store update URL.`);
  const managedPolicy = validateManagedPolicy(profile.managedPolicy || {}, schema);
  const extensionSettings = {
    [extensionId]: {
      installation_mode: 'force_installed',
      update_url: updateUrl,
      toolbar_state: 'force_shown'
    }
  };

  await mkdir(outputDir, { recursive: true });
  await Promise.all([
    writeFile(path.join(outputDir, `${browserConfig.filePrefix}-settings.json`), `${JSON.stringify(extensionSettings, null, 2)}\n`, 'utf8'),
    writeFile(path.join(outputDir, `${browserConfig.filePrefix}-force-install.txt`), `${extensionId};${updateUrl}\n`, 'utf8'),
    writeFile(path.join(outputDir, 'managed-policy.json'), `${JSON.stringify(managedPolicy, null, 2)}\n`, 'utf8'),
    writeFile(path.join(outputDir, 'detect-managed-policy.ps1'), detectionScript(extensionId, managedPolicy, browserConfig.policyRoot), 'utf8'),
    writeFile(path.join(outputDir, 'remediate-managed-policy.ps1'), remediationScript(extensionId, managedPolicy, browserConfig.policyRoot), 'utf8')
  ]);
  return { browser, extensionId, outputDir, managedPolicy };
}

async function main() {
  const browser = String(process.argv[4] || 'edge').toLowerCase();
  const result = await buildIntuneBundle({
    browser,
    extensionId: browser === 'chrome' ? process.env.CAPTIONKEEP_CHROME_EXTENSION_ID : process.env.CAPTIONKEEP_EDGE_EXTENSION_ID,
    profilePath: process.argv[2],
    outputDir: process.argv[3]
  });
  console.log(`Built ${result.browser} Intune deployment bundle for ${result.extensionId} at ${result.outputDir}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
